```turtle
@prefix holon: <https://example.org/holon#> .
@prefix oe: <https://example.org/openevidence#> .
@prefix oeq: <https://example.org/openevidence/questions/> .
@prefix oegen: <https://example.org/openevidence/generated/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<https://example.org/openevidence/questions/q_asthma_efficacy> a holon:ClinicalQuestionHolon ;
  oeq:questionText "How effective is salbutamol compared with other agents for Asthma?"^^rdf:XMLDCAT;
  holon:hasFact [
    a oeq:Fact ;
    oeq:subject <https://example.org/openevidence/drugs/salbutamol> ;
    oeq:predicate oe:treats ;
    oeq:object <https://example.org/openevidence/diseases/asthma> ;
    confidence 0.93,
    level "Level-1A",
    source <https://example.org/openevidence/sources/41005695>,
    effectiveness "effective"
  ] .
```
